# filename: scripts/shadow_report.py
"""Card [8] 'Done when': does ML catch more fraud than rules alone, without flagging more good customers?
Replays the logged decisions three ways against the truth file. Read-only.
  docker compose run --rm --no-deps setup python -m scripts.shadow_report --step-up 0.70"""
import argparse, json, os
from collections import Counter, defaultdict
from concurrent.futures import ThreadPoolExecutor

from common.aws import client

LABELS = os.environ.get("LABELS_FILE", "/data/labels.jsonl")
FLAGGED = ("DECLINE", "STEP_UP")
MODES = ("rules alone", "ML alone", "live (rules+ML)")


def load_decisions(s3, bucket="fraud-labels"):
    keys = [o["Key"] for page in s3.get_paginator("list_objects_v2").paginate(Bucket=bucket, Prefix="decisions/")
            for o in page.get("Contents", [])]
    with ThreadPoolExecutor(16) as ex:
        evts = ex.map(lambda k: json.loads(s3.get_object(Bucket=bucket, Key=k)["Body"].read()), keys)
    return {e["event_id"]: e for e in evts}


def flags(e, step_up):
    """One logged decision -> was it flagged under each mode? (NO_RULE_HIT doesn't start with RULE_)"""
    return {"rules alone": any(r.startswith("RULE_") for r in e["reasons"]),
            "ML alone": float(e["score"]) >= step_up,
            "live (rules+ML)": e["decision"] in FLAGGED}


def cell(text):
    return f"{text:>18s}"


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--step-up", type=float, default=0.70, help="ML STEP_UP threshold: copy it from config.json")
    a = p.parse_args()
    truth = {}
    with open(LABELS) as fh:
        for line in fh:
            r = json.loads(line)
            truth[r["transaction_id"]] = (r["label"], r["scenario_id"])
    seen = load_decisions(client("s3"))

    good, good_n, skipped = Counter(), 0, Counter()
    fraud_hits, fraud_n = Counter(), Counter()
    scen = defaultdict(lambda: dict.fromkeys(MODES, False))   # (label, scenario) -> mode -> caught
    for tid, (label, sid) in truth.items():
        e = seen.get(tid)
        reason = ("no decision stored" if e is None else "fallback" if e.get("fallback")
                  else "no reasons/score" if not e.get("reasons") or e.get("score") is None else None)
        if reason:
            skipped[reason] += 1
            continue
        f = flags(e, a.step_up)
        if label == "normal":
            good_n += 1
            good.update(m for m in MODES if f[m])
        else:
            fraud_n[label] += 1
            for m in MODES:
                fraud_hits[(label, m)] += f[m]
                scen[(label, sid)][m] |= f[m]
    if not good_n:
        raise SystemExit("nothing to compare: do the decision records contain 'reasons' and 'score'?")

    print(f"compared {good_n + sum(fraud_n.values())} payments   skipped: {dict(skipped) or 'none'}")
    print(f"\n{'':26s}" + "".join(cell(m) for m in MODES))
    print(f"{'good customers flagged':26s}" + "".join(cell(f"{good[m] / good_n:.2%}") for m in MODES))
    for label in sorted(fraud_n):
        ids = [k for k in scen if k[0] == label]
        print(f"{label + ' scenarios':26s}" + "".join(cell(f"{sum(scen[k][m] for k in ids)}/{len(ids)}") for m in MODES))
        print(f"{label + ' payments':26s}" + "".join(cell(f"{fraud_hits[(label, m)] / fraud_n[label]:.1%}") for m in MODES))

    rules_caught = sum(fraud_hits[(l, "rules alone")] for l in fraud_n)
    live_caught = sum(fraud_hits[(l, "live (rules+ML)")] for l in fraud_n)
    extra_good = good["live (rules+ML)"] - good["rules alone"]
    print()
    print(("PASS " if live_caught > rules_caught else "FAIL ")
          + f"adding ML catches more fraud payments ({live_caught} vs {rules_caught} with rules alone)")
    print(("PASS " if extra_good <= 0 else "FAIL ")
          + f"adding ML doesn't flag more good customers ({extra_good:+d} vs rules alone)")


if __name__ == "__main__":
    main()
